// Combine the 4 spreadsheet tabs (Global Rules, Content Grid, Product Priority, Resource Links)
// into one formatted reference text block for the LLM prompt - read fresh from
// the actual spreadsheet every run, instead of hardcoded copy in the prompt.
const items = $input.all().map(i => i.json);

// Tell rows from different tabs apart by which columns they have.
const globalRules = items.filter(r => 'Rule' in r && 'Detail' in r);
const contentGrid = items.filter(r => 'Product' in r && 'Stage' in r && 'Full-Block Copy (raw)' in r);
const productPriority = items.filter(r => 'Rank' in r && 'Product' in r && 'Notes' in r && !('Stage' in r));
const resourceLinks = items.filter(r => 'Product' in r && 'Resource Name' in r && 'Used In (Stage/Week)' in r && 'URL' in r);

// --- Global Rules ---
const globalRulesText = globalRules
  .map(r => `### ${r['Rule']}\n${r['Detail']}`)
  .join('\n\n');

// --- Content Grid (skip rows with no Full-Block copy yet - unlaunched products) ---
const contentGridText = contentGrid
  .filter(r => r['Full-Block Copy (raw)'] && String(r['Full-Block Copy (raw)']).trim() !== '')
  .map(r => {
    const week = r['Drip Week #'] ? ` (Week ${r['Drip Week #']})` : '';
    const variant = r['Variant Condition'] ? ` [${r['Variant Condition']}]` : '';
    const cta = r['CTA'] ? ` | CTA override: ${r['CTA']}` : '';
    const notes = r['Dependency / Notes'] ? ` | Notes: ${r['Dependency / Notes']}` : '';
    return `- ${r['Product']} / ${r['Stage']}${week}${variant}\n` +
           `  Full-block: ${r['Full-Block Copy (raw)']}\n` +
           `  One-line: ${r['One-Line Mention (raw)'] || ''}${cta}${notes}`;
  })
  .join('\n');

// --- Product Priority ---
const priorityText = productPriority
  .sort((a, b) => a['Rank'] - b['Rank'])
  .map(r => `${r['Rank']}. ${r['Product']}`)
  .join(', ');

// --- Resource Links ---
// Keep N/A rows because their Notes explicitly tell the model that no sendable URL exists.
const resourceLinksText = resourceLinks
  .map(r => {
    const notes = r['Notes'] ? ` | Notes: ${r['Notes']}` : '';
    return `- ${r['Product']} | ${r['Resource Name']} | Used in: ${r['Used In (Stage/Week)']} | URL: ${r['URL'] || 'N/A'}${notes}`;
  })
  .join('\n');

const referenceText = `GLOBAL RULES (follow all of these exactly as written):
${globalRulesText}

PRODUCT PRIORITY (tiebreak ranking when deal amounts are equal - lower number wins):
${priorityText}

CONTENT GRID (product-specific copy - match each deal's product + normalized stage to a row below):
${contentGridText}

RESOURCE LINKS (approved resource URLs; match by product and Used In stage/week. Never invent or alter a URL):
${resourceLinksText}`;

return [{ json: { referenceText } }];

// Group deals by associated contact so each contact gets ONE consolidated email.
// This node now receives TWO wired inputs merged together: the deals fetch AND
// the pipelines fetch (both feed into this same input index) - wiring it this
// way (instead of reaching out to 'HubSpot - Get pipelines' by name) means
// n8n always treats the pipelines fetch as a real dependency, so testing this
// node (or anything downstream) in isolation always re-runs it too, instead
// of silently skipping it and defaulting every stage label to null.
const items = $input.all();

// Tell the two response shapes apart: a pipelines response's results are
// pipeline objects with a 'stages' array; a deals response's results are
// deal objects with a 'properties' object (no 'stages').
const pipelineItems = [];
const dealItems = [];
for (const item of items) {
  const results = item.json.results;
  if (Array.isArray(results) && results.length > 0 && Array.isArray(results[0].stages)) {
    pipelineItems.push(item);
  } else {
    dealItems.push(item);
  }
}

// Build a stageId -> stageLabel map from the pipelines data, so raw dealstage
// IDs (e.g. 'qualifiedtobuy', '1239370556') can be translated into the
// human-readable stage names the Content Grid is written around.
const stageLabelById = {};
for (const item of pipelineItems) {
  for (const pipeline of (item.json.results || [])) {
    for (const stage of (pipeline.stages || [])) {
      stageLabelById[stage.id] = stage.label;
    }
  }
}
const pipelineLookupError = pipelineItems.length === 0
  ? 'No pipeline data reached this node - check that HubSpot - Get pipelines is wired in and actually returned results.'
  : null;

// HubSpot's list-deals response comes back as ONE item shaped like { results: [...], paging: {...} }
// rather than one item per deal, so unwrap it first.
const deals = dealItems.flatMap(item => {
  if (Array.isArray(item.json.results)) {
    return item.json.results;
  }
  return [item.json];
});

const byContact = {};
for (const deal of deals) {
  // Dedupe: the same contact can appear multiple times with different
  // association types (deal_to_contact, end_user, payor, etc.)
  const contactIds = [...new Set(
    (deal.associations?.contacts?.results || []).map(r => r.id)
  )];

  const rawStage = deal.properties?.dealstage;
  const stageLabel = stageLabelById[rawStage] || null;

  for (const contactId of contactIds) {
    if (!byContact[contactId]) {
      byContact[contactId] = {
        contactId,
        deals: [],
        _pipelineLookupError: pipelineLookupError
      };
    }
    byContact[contactId].deals.push({
      dealname: deal.properties?.dealname,
      dealstage: rawStage,
      dealstageLabel: stageLabel,
      amount: deal.properties?.amount,
      closedate: deal.properties?.closedate,
      owner: deal.properties?.hubspot_owner_id
    });
  }
}

return Object.values(byContact).map(contact => ({ json: contact }));

// Only keep deals whose stage matches one of the 5 stages the Content Grid
// actually has copy for (Qualified to Explore, Demo, Trial, Due Diligence,
// Quote Requested) - drops closed-won/lost deals, other-pipeline deals
// (Ecommerce, default Sales Pipeline), and anything else out of scope.
//
// Real HubSpot labels don't match the spreadsheet's names exactly
// ("Demo Call" vs "Demo", "Due Diligence (IT, Legal, Compliance)" vs
// "Due Diligence") - normalize with a contains-match and rewrite to the
// canonical Content Grid name so downstream matching is a clean exact match.
const knownStages = ['Qualified to Explore', 'Demo', 'Trial', 'Due Diligence', 'Quote Requested'];

function normalizeStage(label) {
  if (!label) return null;
  const lower = label.toLowerCase();
  for (const known of knownStages) {
    if (lower.includes(known.toLowerCase())) {
      return known;
    }
  }
  return null;
}

const items = $input.all();
const filtered = [];

for (const item of items) {
  const contact = item.json;
  const matchedDeals = contact.deals
    .map(deal => ({ ...deal, dealstageLabel: normalizeStage(deal.dealstageLabel) }))
    .filter(deal => deal.dealstageLabel !== null);

  // Skip contacts with no deals in a stage the Content Grid actually covers -
  // nothing relevant to follow up on for them right now.
  if (matchedDeals.length > 0) {
    filtered.push({
      json: {
        ...contact,
        deals: matchedDeals
      }
    });
  }
}

return filtered;

// HubSpot's batch read endpoint takes max 100 IDs per request.
// Collect all grouped contact IDs into the request body shape it expects.
const items = $input.all();
return [{
  json: {
    inputs: items.map(item => ({ id: String(item.json.contactId) }))
  }
}];

// Merge each contact's email/name back onto its grouped deal data, and attach
// the live spreadsheet-driven content reference text (built once per run by
// 'Build content reference text') onto every contact so the LLM prompt can
// use it.
const response = $input.first().json;
const originalContacts = $('Loop Over Contacts').all();

const contactById = {};
for (const result of (response.results || [])) {
  contactById[result.id] = {
    email: result.properties?.email || null,
    firstName: result.properties?.firstname || null,
    lastName: result.properties?.lastname || null
  };
}

let referenceText = '';
try {
  referenceText = $('Build content reference text').first().json.referenceText || '';
} catch (e) {
  // 'Build content reference text' hasn't executed yet in this session (e.g.
  // testing this node in isolation) - fall back to empty rather than crashing.
  // Run the full workflow, or execute that node's branch first, to populate it.
  referenceText = '';
}

return originalContacts.map(item => {
  const contactInfo = contactById[String(item.json.contactId)] || {};
  return {
    json: {
      ...item.json,
      contactEmail: contactInfo.email || null,
      firstName: contactInfo.firstName || null,
      lastName: contactInfo.lastName || null,
      referenceText
    }
  };
});

// DeepSeek Chat Completions returns text at choices[0].message.content.
const responses = $input.all();
const originals = $('Merge emails into contacts').all();

const signature = `
<div style="margin-top:18px;font-family:Arial,Helvetica,sans-serif;font-size:14px;color:#000000;line-height:1.4;">
  <p style="margin:0 0 10px 0;">
    <img
      src="https://www.thebabelgroup.com/wp-content/uploads/2024/09/TBG-dark-stacked-logo.pdf-2.png"
      alt="The Babel Group"
      width="90"
      style="display:block;border:0;width:90px;height:auto;">
  </p>

  <p style="margin:0;">
    <strong>Dr. Rachel Levy, SLPD, CCC-SLP</strong>
  </p>

  <p style="margin:4px 0 0 0;">
    Co-founder, The Babel Group
  </p>

  <p style="margin:4px 0 0 0;">
    +1 (646) 941-7651
  </p>
</div>
`;

return responses.map((response, index) => {
  const original = originals[index]?.json || {};

  let draftEmail =
    response.json.choices?.[0]?.message?.content || '';

  // Clean DeepSeek output
  draftEmail = draftEmail
    .replace(/```html/gi, '')
    .replace(/```/g, '')
    .replace(/<\/?html>/gi, '')
    .replace(/<\/?body>/gi, '')
    .trim();

  // If DeepSeek created a booking CTA but did NOT provide an anchor/link,
  // remove the incomplete CTA paragraph.
  if (!/<a\s+[^>]*href=/i.test(draftEmail)) {
    draftEmail = draftEmail
      .replace(
        /<p[^>]*>\s*If you'd like to see Voiceitt in action,\s*grab time here:\s*<\/p>/gi,
        ''
      )
      .replace(
        /If you'd like to see Voiceitt in action,\s*grab time here:\s*$/gi,
        ''
      )
      .trim();
  }

  // Add spacing before signature
  draftEmail += `

${signature}`;

  // Convert Markdown links to HTML links
draftEmail = draftEmail.replace(
  /\[Click here\]\((https?:\/\/[^)\s]+)\)/gi,
  '<a href="$1">Click here</a>'
);

// Remove accidental ". Rachel" or "%20Rachel" from URLs
draftEmail = draftEmail.replace(
  /href="([^"]+?)(?:\.?\s*Rachel|%20Rachel)"/gi,
  'href="$1"'
);

  return {
    json: {
      contactId: original.contactId,
      contactEmail: original.contactEmail,
      firstName: original.firstName,
      lastName: original.lastName,
      company: original.company,
      deals: original.deals,
      draftEmail,
      model: response.json.model || 'deepseek-v4-flash',
      promptTokens: response.json.usage?.prompt_tokens || null,
      outputTokens: response.json.usage?.completion_tokens || null,
      totalTokens: response.json.usage?.total_tokens || null
    }
  };
});

// Generate a unique token per draft so the standalone approval webhook can
// look up this exact pending draft later, without depending on any
// in-process 'Wait' execution staying alive.
const items = $input.all();
return items.map(item => ({
  json: {
    ...item.json,
    approvalToken: `${Date.now()}-${Math.random().toString(36).slice(2, 12)}`
  }
}));
